from pathlib import Path
code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = {}
    # The task contains solid 3x3 blocks. Extend each block's middle row
    # and column across the grid.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                # Process only the top-left corner of each block.
                if r and all(grid[y][x] == color for y in range(r - 1, r + 2) for x in range(c, c + 3)):
                    continue
                if c and all(grid[y][x] == color for y in range(r, r + 3) for x in range(c - 1, c + 2)):
                    continue
                cr, cc = r + 1, c + 1
                for x in range(w): rays.setdefault((cr, x), set()).add(color)
                for y in range(h): rays.setdefault((y, cc), set()).add(color)
    for (r, c), colors in rays.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
'''
